namespace Astrea;

[CreateAssetMenu(fileName = "BossLinkBoostEffect", menuName = "Data/Battle/Effects/BossLinkBoost Effect")]
public class BossLinkBoostEffect : BoostEffect
{
	public override void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		effectOwner.GetComponent<UnitsDiceActivation>().Boosted(boost: false);
	}
}
